import javax.swing.*;
import java.awt.*;
import java.lang.reflect.Field;
import java.util.*;

/** The same validated settings form is used by live creation and batch experiments. */
public final class WorldSettingsPanel extends JPanel {
    final JComboBox<String> presets=new JComboBox<>(WorldConfig.PRESETS);
    final JTextField seed=new JTextField(Long.toString(new Random().nextLong()),20);
    private final Map<Field,JComponent> editors=new LinkedHashMap<>();
    public WorldSettingsPanel(WorldConfig initial,long initialSeed){
        super(new BorderLayout(12,12));setBorder(BorderFactory.createEmptyBorder(16,16,16,16));
        JPanel basic=new JPanel(new GridLayout(0,2,10,8));basic.add(new JLabel("Preset"));basic.add(presets);basic.add(new JLabel("Replayable world seed"));seed.setText(Long.toString(initialSeed));basic.add(seed);
        UiTheme.tip(seed,"A signed 64-bit seed. Identical settings, genomes and seed reproduce the same world.");
        UiHelp.choices(presets,i->switch(i){case 1->"Continuous ecology: 60 prey, hunters off, food 55, mutation 12%, seasons on. Audit seeds survived 30 minutes; new seeds can differ.";case 2->"Steady observation: food 100, mutation 5%, hunters and seasons off.";case 3->"Experimental coexistence: food 100, mutation 5%, seasons off, 16 sources. Only 2/5 fresh seeds retained both roles at 30 minutes.";case 4->"Explicit selection every 45 seconds, top 12 per role, with inspection before breeding.";default->"Original settings remain available as the classic preset. The app starts with hunter-free Continuous ecology after held-out evaluation.";});
        add(basic,BorderLayout.NORTH);
        JTabbedPane groups=new JTabbedPane();groups.setTabLayoutPolicy(JTabbedPane.SCROLL_TAB_LAYOUT);Map<String,JPanel> panels=new LinkedHashMap<>();
        for(Field f:WorldConfig.fields()){
            WorldConfig.Setting setting=f.getAnnotation(WorldConfig.Setting.class);
            JPanel panel=panels.computeIfAbsent(setting.group(),g->{JPanel p=new JPanel(new GridBagLayout());JPanel anchored=new JPanel(new BorderLayout());anchored.add(p,BorderLayout.NORTH);JScrollPane scroll=new JScrollPane(anchored);scroll.getVerticalScrollBar().setUnitIncrement(20);groups.addTab(g,scroll);return p;});
            JComponent editor;
            try{Object value=f.get(initial);if(f.getType()==boolean.class){JCheckBox b=new JCheckBox();b.setSelected((boolean)value);editor=b;}
            else if(f.getType().isEnum()){JComboBox<Simulation.Mode> b=new JComboBox<>(Simulation.Mode.values());b.setSelectedItem(value);editor=b;}
            else{double v=((Number)value).doubleValue();double step=f.getType()==int.class?1:v!=0&&Math.abs(v)<.01?.00001:v!=0&&Math.abs(v)<1?.01:.1;JSpinner spinner=new JSpinner(new SpinnerNumberModel(v,setting.min(),setting.max(),step));spinner.setEditor(new JSpinner.NumberEditor(spinner,f.getType()==int.class?"0":"0.########"));editor=spinner;}}
            catch(IllegalAccessException e){throw new IllegalStateException(e);}
            UiTheme.tip(editor,setting.help());JLabel label=new JLabel(WorldConfig.label(f));UiTheme.tip(label,setting.help());editors.put(f,editor);
            GridBagConstraints c=new GridBagConstraints();c.gridy=panel.getComponentCount()/2;c.gridx=0;c.weightx=.35;c.anchor=GridBagConstraints.WEST;c.fill=GridBagConstraints.HORIZONTAL;c.insets=new Insets(7,12,7,12);panel.add(label,c);c.gridx=1;c.weightx=.65;panel.add(editor,c);
        }
        groups.setPreferredSize(new Dimension(790,510));add(groups,BorderLayout.CENTER);
        JPanel actions=new JPanel(new GridLayout(0,3,8,8));
        JButton random=new JButton("Random seed"),reset=new JButton("Reset to selected preset"),load=new JButton("Load settings…"),save=new JButton("Save settings…");
        UiTheme.tip(random,"Choose a new replayable seed without changing settings.");UiTheme.tip(reset,"Replace all fields with the selected preset; preserve the entered seed.");UiTheme.tip(load,"Read a reusable .settings file. It does not resume a running world.");UiTheme.tip(save,"Write the complete validated settings to a reusable .settings file; including the replay seed.");
        random.addActionListener(e->seed.setText(Long.toString(new Random().nextLong())));reset.addActionListener(e->apply(WorldConfig.preset((String)presets.getSelectedItem())));presets.addActionListener(e->apply(WorldConfig.preset((String)presets.getSelectedItem())));
        load.addActionListener(e->{JFileChooser c=new JFileChooser();if(c.showOpenDialog(this)==JFileChooser.APPROVE_OPTION)try{WorldConfig loaded=WorldConfig.read(c.getSelectedFile().toPath());Long loadedSeed=WorldConfig.readSeed(c.getSelectedFile().toPath());apply(loaded);if(loadedSeed!=null)seed.setText(loadedSeed.toString());}catch(Exception ex){error(ex);}});
        save.addActionListener(e->{JFileChooser c=new JFileChooser();c.setSelectedFile(new java.io.File("my-world.settings"));if(c.showSaveDialog(this)==JFileChooser.APPROVE_OPTION){if(c.getSelectedFile().exists()&&JOptionPane.showConfirmDialog(this,"Replace these settings?","Save settings",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;try{value().write(c.getSelectedFile().toPath(),seed());}catch(Exception ex){error(ex);}}});
        JButton scale=new JButton("Scale space & density…");UiTheme.tip(scale,"Scale dimensions, population counts/caps and food supply by area, with integer rounding. Review all adjusted fields before creating the world.");scale.addActionListener(e->{JSpinner factor=new JSpinner(new SpinnerNumberModel(1.5,.5,3,.1));if(JOptionPane.showConfirmDialog(this,factor,"Linear dimension multiplier",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION)try{factor.commitEdit();apply(value().scaledDensity(((Number)factor.getValue()).doubleValue()));}catch(Exception ex){error(ex);}});
        for(JButton b:new JButton[]{random,reset,load,save,scale})actions.add(b);add(actions,BorderLayout.SOUTH);UiTheme.apply(this);
    }
    void error(Exception ex){JOptionPane.showMessageDialog(this,ex.getMessage(),"Settings",JOptionPane.ERROR_MESSAGE);}
    public long seed(){try{return Long.parseLong(seed.getText().trim());}catch(NumberFormatException e){throw new IllegalArgumentException("Seed must be a signed 64-bit whole number.");}}
    public WorldConfig value(){WorldConfig c=new WorldConfig();try{for(var entry:editors.entrySet()){Field f=entry.getKey();JComponent e=entry.getValue();if(e instanceof JSpinner spinner){spinner.commitEdit();double n=((Number)spinner.getValue()).doubleValue();if(f.getType()==int.class){if(n!=Math.rint(n))throw new IllegalArgumentException(WorldConfig.label(f)+" must be a whole number.");f.setInt(c,(int)n);}else f.setDouble(c,n);}else if(e instanceof JCheckBox check)f.setBoolean(c,check.isSelected());else f.set(c,((JComboBox<?>)e).getSelectedItem());}}catch(ReflectiveOperationException|java.text.ParseException ex){throw new IllegalArgumentException("Invalid settings: "+ex.getMessage(),ex);}c.validate();seed();return c;}
    public void apply(WorldConfig c){try{for(var entry:editors.entrySet()){Object v=entry.getKey().get(c);JComponent e=entry.getValue();if(e instanceof JSpinner spinner)spinner.setValue(((Number)v).doubleValue());else if(e instanceof JCheckBox check)check.setSelected((boolean)v);else ((JComboBox<?>)e).setSelectedItem(v);}}catch(IllegalAccessException ex){throw new IllegalStateException(ex);}}
    public record Choice(WorldConfig config,long seed){}
    public static Choice edit(Component owner,WorldConfig initial,long seed,String title,boolean newWorld){WorldSettingsPanel panel=new WorldSettingsPanel(initial,seed);for(int i=0;i<WorldConfig.PRESETS.length;i++)if(WorldConfig.preset(WorldConfig.PRESETS[i]).properties().equals(initial.properties())){panel.presets.setSelectedIndex(i);break;}JPanel body=new JPanel(new BorderLayout(12,12));if(newWorld){JTabbedPane tabs=new JTabbedPane();JPanel summary=new JPanel(new GridLayout(0,1,0,15));summary.setBorder(BorderFactory.createEmptyBorder(28,28,28,28));summary.add(new JLabel("Choose a preset, then open Advanced Settings to customize your world."));summary.add(new JLabel("Creating a world replaces the current dish. Save a checkpoint first to keep it."));JComboBox<String> quick=new JComboBox<>(panel.presets.getModel());UiTheme.tip(quick,"Choose a complete biological preset, then customize it on the Advanced Settings tab.");summary.add(quick);JTextField basicSeed=new JTextField();basicSeed.setDocument(panel.seed.getDocument());summary.add(new JLabel("Replayable seed"));summary.add(basicSeed);UiTheme.tip(basicSeed,"The exact seed used to initialize this world.");tabs.addTab("New World",summary);tabs.addTab("Advanced Settings",panel);body.add(tabs);}else body.add(panel);
        JDialog dialog=new JDialog(SwingUtilities.getWindowAncestor(owner),title,Dialog.ModalityType.APPLICATION_MODAL);dialog.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);dialog.setResizable(true);Choice[] result={null};JPanel buttons=new JPanel(new FlowLayout(FlowLayout.RIGHT));JButton cancel=new JButton("Cancel"),accept=new JButton(newWorld?"Create world":"Apply settings");UiTheme.tip(cancel,"Close without changing the current world or settings.");UiTheme.tip(accept,"Validate all fields and use these settings.");cancel.addActionListener(e->dialog.dispose());accept.addActionListener(e->{try{result[0]=new Choice(panel.value(),panel.seed());dialog.dispose();}catch(Exception ex){panel.error(ex);}});buttons.add(cancel);buttons.add(accept);body.add(buttons,BorderLayout.SOUTH);dialog.setContentPane(body);Rectangle bounds=GraphicsEnvironment.getLocalGraphicsEnvironment().getMaximumWindowBounds();dialog.setSize(Math.min(940,bounds.width),Math.min(820,bounds.height));dialog.setMinimumSize(new Dimension(Math.min(740,bounds.width),Math.min(520,bounds.height)));dialog.setLocationRelativeTo(owner);UiTheme.apply(dialog);dialog.setVisible(true);return result[0];}
    public static Simulation create(Component owner,Simulation current){WorldConfig template=WorldConfig.preset("Continuous ecology");long seed=new Random().nextLong();while(true){Choice c=edit(owner,template,seed,"New World",true);if(c==null)return null;try{return new Simulation(c.config,c.seed);}catch(Exception ex){JOptionPane.showMessageDialog(owner,ex.getMessage(),"Could not create world",JOptionPane.ERROR_MESSAGE);template=c.config;seed=c.seed;}}}
}
